/* A shop's carriers (carrier selector): `physical_carrier_prefs`, one row per store holding the carriers it starred (up to 12 names), the one it set as its default, the one it last shipped with, and the carriers it added itself because no list has them (up to 20, each a name and an optional tracking link with {tracking} where the number goes). Names only: no prices, services or delivery times are kept here, those come from the shop's connected shipping app each time. Row level security on: the store's owner can read their own row, nobody else can; every write goes through the server with its own key after the owner is checked. No existing row changes, and a shipment's saved carrier and tracking link are untouched. Until it runs, the carrier picker still lists every carrier and the shop's connected ones, and starring, a default and a carrier of its own are not offered. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.physical_carrier_prefs (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, favourites text[] NOT NULL DEFAULT '{}'::text[], default_carrier text, last_carrier text, custom_carriers jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT physical_carrier_prefs_pkey PRIMARY KEY (creator_id), CONSTRAINT physical_carrier_prefs_favourites_check CHECK (cardinality(favourites) <= 12), CONSTRAINT physical_carrier_prefs_names_check CHECK ((default_carrier IS NULL OR char_length(default_carrier) BETWEEN 1 AND 60) AND (last_carrier IS NULL OR char_length(last_carrier) BETWEEN 1 AND 60)), CONSTRAINT physical_carrier_prefs_custom_check CHECK (CASE WHEN jsonb_typeof(custom_carriers) = 'array' THEN jsonb_array_length(custom_carriers) <= 20 AND pg_column_size(custom_carriers) < 16384 ELSE false END));
ALTER TABLE public.physical_carrier_prefs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.physical_carrier_prefs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.physical_carrier_prefs TO authenticated;
DROP POLICY IF EXISTS physical_carrier_prefs_owner_read ON public.physical_carrier_prefs;
CREATE POLICY physical_carrier_prefs_owner_read ON public.physical_carrier_prefs FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.physical_carrier_prefs TO service_role;
notify pgrst, 'reload schema';
